def expected_stage(root):
    result = {}
    extensions = ('.c', '.cc', '.cpp', '.h', '.hpp')
    for path in (root / 'src').rglob('*'):
        if not path.is_file():
            continue
        name = path.relative_to(root).as_posix()
        target = None
        if name == 'src/config.h' or name.startswith(('src/core/', 'src/hal/')):
            target = name
        elif name.startswith('src/app/'):
            tail = path.relative_to(root / 'src/app')
            if tail.parts[0] == 'src':
                target = tail.as_posix()
            elif tail.suffix in extensions:
                target = 'src/app/' + tail.as_posix()
            elif len(tail.parts) == 1 and tail.name != '.gitkeep':
                target = tail.name
        if target is not None:
            if target in result:
                raise ValueError('Fixture stage collision: ' + target)
            result[target] = path.read_bytes()
    return result

